function tst(i){const t=S.teams[i],k0=CUR,s={sw:0,sl:0,mw:0,ml:0},H=[],TR=[];let earn=0,champs=0;
 S.tours.forEach((_,k)=>{setCur(k);if(!inT(i))return;const q=st(i);s.sw+=q.sw;s.sl+=q.sl;s.mw+=q.mw;s.ml+=q.ml;
  let lab=plc(i);if(X.cm!=null)lab=X.cm==i?'1st':lab=='1st'?'2nd':lab;
  const fin=X.st!='Akan datang'&&/^\d/.test(lab),pr=fin?X.prize*pp(lab)/100:0;TR.push({k,n:X.n,g:X.g,tier:X.tier||'',lab,pr,fin,q,gl:grpOf(i)});if(fin){earn+=pr;if(lab=='1st')champs++}
  XM().forEach(([m,x])=>{if(x.w!=null&&(x.a==i||x.b==i))H.push([X.n,m[3],x,k])});brH(i).forEach(h=>H.push([X.n,h[0],null,k,h[1],h[2]]))});
 setCur(k0);t.a.forEach(a=>{earn+=+a[3]||0;if(a[1]=='1st')champs++});s.wr=s.sw+s.sl?Math.round(s.sw*100/(s.sw+s.sl)):0;return{s,H,TR,earn,champs}}
async function hs(s){try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){let h=5381;for(const c of s)h=(h*33^c.charCodeAt(0))>>>0;return'x'+h}}
