const vloginHtml=()=>`<div class="card" style="max-width:380px;margin:30px auto"><h1 style="font-size:22px">Login Peserta</h1><p class="mu">Masuk dengan username dan password akunmu.</p><input type="text" id="vu" placeholder="Username" autocomplete="username" autocapitalize="none" style="width:100%;margin-bottom:8px;padding:8px 10px;border:1px solid var(--bd);border-radius:6px;background:var(--card);color:var(--tx);min-height:40px"><input type="password" id="vp" autocomplete="current-password" placeholder="Password" style="width:100%;padding:8px 10px;border:1px solid var(--bd);border-radius:6px;background:var(--card);color:var(--tx);min-height:40px" onkeydown="if(event.key=='Enter')vlogin()"><p><button onclick="vlogin()">Masuk</button></p><p class="mu">Lupa password? Hubungi admin untuk direset.</p></div>`;
