async function chpwPeserta(){const o=document.getElementById('cp0').value,n=document.getElementById('cp1').value,k=document.getElementById('cp2').value;if(n.length<6)return toast('Password baru minimal 6 karakter');if(n!==k)return toast('Ulangi password baru tidak sama');try{const r=await fetch('/api/peserta-password',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+PTK},body:JSON.stringify({old:o,new:n})});const j=await r.json().catch(()=>({}));if(r.ok){PTK=j.token||PTK;try{sessionStorage.setItem('esppt',PTK)}catch(e){}['cp0','cp1','cp2'].forEach(i=>document.getElementById(i).value='');toast('Password diubah ✓')}else if(r.status==401){toast('Sesi habis, login lagi');vout()}else toast(j.error||'Gagal mengubah password')}catch(e){toast('Gagal terhubung ke server')}}
