function timSaya(){if(!VW||!PTK)return'<div class="card">Masuk sebagai peserta dulu.</div>';
 if(!TM.loaded){if(!TM.loading)loadTM();return'<div class="card">Memuat tim…</div>'}
 const st='width:100%;margin-bottom:8px;padding:8px 10px;border:1px solid var(--bd);border-radius:6px;background:var(--card);color:var(--tx);min-height:40px',row=TM.row,f=TM.f;
 const badge=!row?'':row.status=='pending'?'<p><b>⏳ Menunggu persetujuan admin.</b> Tim baru tampil di situs setelah disetujui.</p>':row.status=='approved'?'<p><b>✅ Disetujui.</b> Tim kamu sudah tampil di situs. Kalau kamu mengubah data di bawah, perubahan tampil setelah disetujui admin lagi.</p>':'<p><b>❌ Ditolak.</b>'+(row.note?' Catatan admin: '+esc(row.note):'')+' Perbaiki lalu ajukan lagi.</p>';
 if(!f)return`<div class="crumb">Beranda › Tim saya</div><div class="card" style="max-width:520px;margin:20px auto"><h1 style="font-size:22px">Tim saya</h1><p class="mu">Kamu masuk sebagai penonton. Kalau mau mendaftarkan tim, buat pengajuan. Admin akan memeriksanya dulu sebelum tim tampil di situs.</p><p><button onclick="TM.f=tmBlank();render()">Buat tim</button></p></div>`;
 const live=new Set(((row&&row.live&&row.live.divs)||[]).map(d=>d.did));
 const gopt=g=>'<option value="">— pilih game —</option>'+S.games.map(x=>`<option value="${esc(x.id)}"${x.id==g?' selected':''}>${esc(x.n)}</option>`).join('');
 const dv=f.divs.map((d,i)=>`<div class="card" style="margin:8px 0"><b>Divisi ${i+1}</b><select onchange="TM.f.divs[${i}].g=this.value" style="${st};margin-top:6px" aria-label="Game">${gopt(d.g)}</select><input type="text" value="${esc(d.n)}" maxlength="50" placeholder="Nama divisi (misal ${esc(f.org.n||'Nama Tim')} Mobile Legends)" onchange="TM.f.divs[${i}].n=this.value" style="${st}" aria-label="Nama divisi"><label class="f">Pemain, satu per baris, format "ID" atau "ID | Peran"</label><textarea rows="6" maxlength="600" onchange="TM.f.divs[${i}].p=this.value" style="${st}" aria-label="Pemain" placeholder="username | posisi&#10;username | posisi&#10;username | posisi&#10;username | posisi&#10;username | posisi">${esc(d.p)}</textarea>${live.has(d.did)?'<p class="mu">Divisi ini sudah disetujui. Untuk menghapusnya hubungi admin.</p>':f.divs.length>1?`<button class="dn" onclick="TM.f.divs.splice(${i},1);render()">Hapus divisi</button>`:''}</div>`).join('');
 return`<div class="crumb">Beranda › Tim saya</div><div class="card" style="max-width:560px;margin:20px auto"><h1 style="font-size:22px">Tim saya</h1>${badge}
<label class="f">Nama tim</label><input type="text" value="${esc(f.org.n)}" maxlength="40" onchange="TM.f.org.n=this.value" style="${st}">
<label class="f">Tag (maks. 4 huruf/angka, kosong = otomatis)</label><input type="text" value="${esc(f.org.t)}" maxlength="4" onchange="TM.f.org.t=this.value.toUpperCase()" style="${st}">
<label class="f">Negara (2 huruf, misal ID)</label><input type="text" value="${esc(f.org.c)}" maxlength="2" onchange="TM.f.org.c=this.value.toUpperCase()" style="${st}">
<label class="f">Deskripsi singkat</label><textarea rows="3" maxlength="300" onchange="TM.f.org.desc=this.value" style="${st}">${esc(f.org.desc)}</textarea>
<div class="row" style="border:0;padding:0 0 8px">${f.org.logo?`<span class="lg lgi" style="width:56px;height:56px"><img src="${f.org.logo}" alt="Logo"></span>`:'<span class="mu">Belum ada logo</span>'}<label class="btn">${f.org.logo?'Ganti logo':'Upload logo'}<input type="file" accept="image/*" hidden onchange="tmLogo(this)"></label>${f.org.logo?'<button class="sc" onclick="TM.f.org.logo=\'\';render()">Hapus logo</button>':''}</div>
<h3>Divisi</h3>${dv}${f.divs.length<6?'<p><button class="sc" onclick="TM.f.divs.push({did:tmId(),n:\'\',g:\'\',p:\'\'});render()">+ Tambah divisi</button></p>':''}
<p><button onclick="tmSubmit()"${TM.busy?' disabled':''}>Ajukan ke admin</button> ${row&&row.live?'':`<button class="dn" onclick="tmDel()">${row?'Hapus pengajuan':'Batal'}</button>`}</p></div>`}
async function tmDel(){if(!TM.row){TM.f=null;return render()}if(!confirm('Hapus pengajuan tim ini? Data yang sudah kamu isi akan hilang.'))return;
 try{const r=await fetch('/api/tim-saya',{method:'DELETE',headers:{Authorization:'Bearer '+PTK}});const j=await r.json().catch(()=>({}));if(r.ok){TM.row=null;TM.f=null;TM.loaded=false;toast('Pengajuan dihapus');render()}else if(r.status==401){toast('Sesi habis, login lagi');vout()}else toast(j.error||'Gagal menghapus')}catch(e){toast('Gagal terhubung ke server')}}
function tmLogo(el){const f=el.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const Q=256,c=document.createElement('canvas');c.width=c.height=Q;const W=im.naturalWidth||Q,H=im.naturalHeight||Q,k=Math.min(Q/W,Q/H),w=W*k,h=H*k;c.getContext('2d').drawImage(im,(Q-w)/2,(Q-h)/2,w,h);let u=c.toDataURL('image/png');if(u.length>190000)u=c.toDataURL('image/webp',.9);if(u.length>190000)u=c.toDataURL('image/jpeg',.8);if(u.length>190000)return toast('Logo terlalu besar, pakai gambar lain');TM.f.org.logo=u;render()};im.onerror=()=>toast('File bukan gambar');im.src=r.result};r.readAsDataURL(f)}
async function tmSubmit(){const f=TM.f;if(!f)return;if((f.org.n||'').trim().length<2)return toast('Isi nama tim dulu');
 const divs=f.divs.map(d=>({did:d.did,n:(d.n||'').trim()||((f.org.n||'').trim()+' '+((S.games.find(x=>x.id==d.g)||{}).n||'')).trim(),g:d.g||'',r:(d.p||'').split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{const m=x.split('|');return[(m[0]||'').trim()||'TBD',(m[1]||'').trim()]})}));
 if(divs.some(d=>d.n.length<2))return toast('Isi nama divisi');
 TM.busy=true;render();
 try{const r=await fetch('/api/tim-saya',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+PTK},body:JSON.stringify({payload:{org:f.org,divs}})});const j=await r.json().catch(()=>({}));TM.busy=false;if(r.ok){TM.loaded=false;toast('Diajukan, menunggu persetujuan admin');render()}else if(r.status==401){toast('Sesi habis, login lagi');vout()}else{toast(j.error||'Gagal mengajukan');render()}}catch(e){TM.busy=false;toast('Gagal terhubung ke server');render()}}
