function tcards(lim){const k0=CUR,L=TO(),sh=lim&&!OPEN.hc?L.slice(0,lim):L,h=sh.map(([_,k])=>{setCur(k);const s=sts(),c=champ();return`<div class="tile" style="align-items:stretch;text-align:left" onclick="go('/t/${k}')"><div style="display:flex;justify-content:space-between;gap:6px">${bd(s,stc(s))}<span class="mu">${gname(X.g)?esc(gname(X.g))+' · ':''}${X.size} tim${X.mode=='br'?' · Point System':''}</span></div>${X.tier?`<div>${tierB(X.tier)}</div>`:''}<b>${esc(X.n)}</b><span class="mu">${esc(X.date)} · ${esc(X.loc)}</span><span>${fmt(X.prize)}</span><span class="mu">Juara: ${c!=null&&S.teams[c]?esc(S.teams[c].n):'–'}</span></div>`}).join('');setCur(k0);const more=lim&&L.length>lim?`<div class="more"><button onclick="hTog('hc')">Detail${tri(OPEN.hc)}</button></div>`:'';return`<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(min(100%,240px),1fr))">${h}</div>${more}`}
function tlist(){return`<div class="crumb">Beranda › Pertandingan</div><h1>Pertandingan</h1><div style="margin-top:12px">${tcards()}</div>`}
function tsel(){return`<div class="card" style="margin-bottom:12px"><div class="row" style="border:0"><b>Pertandingan:</b><select onchange="EI=+this.value;render()">${S.tours.map((t,k)=>`<option value="${k}" ${k==EI?'selected':''}>${esc(t.n)}</option>`).join('')}</select><button onclick="addTour()">+ Pertandingan baru</button><button class="sc" onclick="S.feat=EI;save();render()">${S.feat==EI?'★ Unggulan di beranda':'☆ Jadikan unggulan'}</button>${DELT==EI?`<button class="dn" onclick="delTour()">Yakin hapus?</button><button class="sc" onclick="DELT=-1;render()">Batal</button>`:S.tours.length>1?`<button class="dn" onclick="DELT=EI;render()">Hapus pertandingan</button>`:''}</div></div>`}
function setN(v){let n=Math.round(+v);if(!(n>=3))n=3;if(n>32)n=32;X.size=n;setSize();norm();save();render()}
function addTour(){S.tours.push(NT({n:'Pertandingan Baru',g:X.g,slots:Array(32).fill(null)}));EI=S.tours.length-1;save();render()}
function delTour(){S.tours.splice(EI,1);if(S.feat==EI)S.feat=0;else if(S.feat>EI)S.feat--;EI=0;DELT=-1;save();render()}

async function chpw(){const o=document.getElementById('op').value,n=document.getElementById('np').value;if(n.length<8){toast('Sandi baru minimal 8 karakter');return}try{const r=await api('/api/password',{method:'POST',body:JSON.stringify({old:o,new:n})});const j=await r.json();if(r.ok){TOK=j.token;try{sessionStorage.setItem('esptok',TOK)}catch(e){}document.getElementById('op').value='';document.getElementById('np').value='';toast('Sandi diubah ✓')}else toast(j.error||'Gagal')}catch(e){toast('Gagal terhubung ke server')}}
